            "<span style=\"color:#F97583\">  await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">collectPaymentMethod</span><span style=\"color:#E1E4E8\">({ paymentIntent });</span>",
